-- +goose Up
-- Service pages redesign: all services now use LandingLayout (copy defaults in src/content/service-landings.ts).
-- Replaces the rich-text bodies, whose wording conflicted with CFP Res. 010/2005 Art. 20 and, on /plantao, invited
-- people at risk to wait for a WhatsApp reply. WhatsApp texts and analytics keys are untouched. The previous values
-- are kept in revisions (entity_type='service_body_backup') and restored by Down.
INSERT INTO revisions (entity_type, entity_id, version, data, message)
SELECT 'service_body_backup', p.slug, 1,
  jsonb_build_object('title', p.title, 'subtitle', p.subtitle, 'meta_title', p.meta_title, 'meta_description', p.meta_description,
    'cta_text', s.cta_text, 'body', s.body, 'published_body', s.published_body),
  'Before migration 0015 (service pages redesign)'
FROM services s JOIN pages p ON p.id = s.page_id
WHERE p.slug IN ('psicoterapia','foco-organizacao','plantao','terapia-de-casal','autoconhecimento','supervisao','lgbtqia')
ON CONFLICT (entity_type, entity_id, version) DO NOTHING;

