-- +goose Down
UPDATE pages p SET title = r.data->>'title', subtitle = r.data->>'subtitle', meta_title = r.data->>'meta_title', meta_description = r.data->>'meta_description', updated_at = now()
FROM revisions r WHERE r.entity_type = 'service_body_backup' AND r.entity_id = p.slug::text;
UPDATE services s SET cta_text = r.data->>'cta_text', body = r.data->'body', published_body = r.data->'published_body', updated_at = now()
FROM revisions r JOIN pages p ON r.entity_id = p.slug::text WHERE r.entity_type = 'service_body_backup' AND s.page_id = p.id;
DELETE FROM revisions WHERE entity_type = 'service_body_backup';
